import{_ as a,o as s,c as n,ai as d}from"./chunks/framework.QGT6ovkH.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),t={name:"architecture.md"};function i(o,e,r,c,l,p){return s(),n("div",null,[...e[0]||(e[0]=[d(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/architecture.md for this page in Markdown format</div><h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>opencode-team-lead</code> is an OpenCode plugin that injects agents into the IDE configuration at startup. It has zero npm dependencies — only Node.js builtins (<code>node:fs/promises</code>, <code>node:path</code>, <code>node:url</code>). Pure ESM, no build step.</p><p>The entry point is <code>index.js</code>. It exports <code>TeamLeadPlugin</code>, an async function that loads agent prompts from disk and returns an object with two hooks: <code>config</code> and <code>event</code>.</p><h2 id="plugin-hooks" tabindex="-1">Plugin hooks <a class="header-anchor" href="#plugin-hooks" aria-label="Permalink to &quot;Plugin hooks&quot;">​</a></h2><h3 id="config-hook" tabindex="-1"><code>config</code> hook <a class="header-anchor" href="#config-hook" aria-label="Permalink to &quot;\`config\` hook&quot;">​</a></h3><p>Called by OpenCode to construct the agent configuration. The hook:</p><ol><li>Reads the user&#39;s existing config (<code>input.agent</code>)</li><li>Injects all agent definitions (team-lead + all sub-agents)</li><li>Merges user overrides from <code>opencode.json</code> on top of plugin defaults</li></ol><p><strong>Config merge behavior:</strong></p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">input.agent[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;team-lead&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // plugin defaults</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  temperature: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  variant: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;max&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ...</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // user overrides (applied on top)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">userConfigRest,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // prompt always sourced from plugin — cannot be overridden</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prompt: teamLeadPrompt,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // permissions deep-merged, not replaced</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  permission: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mergePermissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(defaultPermission, userConfigRest.permission),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>Permissions are merged one level deeper via <code>mergePermissions</code>: nested keys (like <code>read</code> or <code>bash</code> which are objects) are shallow-merged rather than replaced. This means users can add permissions without accidentally removing plugin defaults.</p><h3 id="event-hook" tabindex="-1"><code>event</code> hook <a class="header-anchor" href="#event-hook" aria-label="Permalink to &quot;\`event\` hook&quot;">​</a></h3><p>Listens for <code>session.created</code> and creates the three artifact directories on session start:</p><ul><li><code>docs/exec-plans/</code></li><li><code>docs/briefs/</code></li><li><code>docs/specs/</code></li></ul><p>This is a best-effort operation — if the directories already exist, it&#39;s a no-op. This prevents the planning and brainstorm agents from failing with permission errors on a fresh project.</p><h2 id="agent-hierarchy" tabindex="-1">Agent hierarchy <a class="header-anchor" href="#agent-hierarchy" aria-label="Permalink to &quot;Agent hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenCode IDE</span></span>
<span class="line"><span>├── team-lead                [mode: all]</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├─► review-manager       [mode: subagent]</span></span>
<span class="line"><span>│   │     ├─► requirements-reviewer  [mode: subagent]</span></span>
<span class="line"><span>│   │     ├─► code-reviewer          [mode: subagent]</span></span>
<span class="line"><span>│   │     └─► security-reviewer      [mode: subagent]</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├─► bug-finder           [mode: subagent]</span></span>
<span class="line"><span>│   ├─► planning             [mode: all]</span></span>
<span class="line"><span>│   └─► researcher           [mode: subagent]</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── brainstorm               [mode: all — runs before team-lead]</span></span>
<span class="line"><span>├── harness                  [mode: all — triggered post-feature or by user]</span></span>
<span class="line"><span>└── gardener                 [mode: all — periodic maintenance]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><table tabindex="0"><thead><tr><th>Agent</th><th>Mode</th><th>Temperature</th><th>Variant</th></tr></thead><tbody><tr><td><code>team-lead</code></td><td><code>all</code></td><td>0.3</td><td>max</td></tr><tr><td><code>review-manager</code></td><td><code>subagent</code></td><td>0.2</td><td>max</td></tr><tr><td><code>requirements-reviewer</code></td><td><code>subagent</code></td><td>0.1</td><td>max</td></tr><tr><td><code>code-reviewer</code></td><td><code>subagent</code></td><td>0.2</td><td>max</td></tr><tr><td><code>security-reviewer</code></td><td><code>subagent</code></td><td>0.1</td><td>max</td></tr><tr><td><code>bug-finder</code></td><td><code>all</code></td><td>0.2</td><td>max</td></tr><tr><td><code>harness</code></td><td><code>all</code></td><td>0.2</td><td>max</td></tr><tr><td><code>planning</code></td><td><code>all</code></td><td>0.3</td><td>max</td></tr><tr><td><code>gardener</code></td><td><code>all</code></td><td>0.2</td><td>max</td></tr><tr><td><code>brainstorm</code></td><td><code>all</code></td><td>0.5</td><td>max</td></tr><tr><td><code>researcher</code></td><td><code>subagent</code></td><td>0.2</td><td>max</td></tr></tbody></table><h2 id="permission-model" tabindex="-1">Permission model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission model&quot;">​</a></h2><p>The principle is <strong>deny-all, explicit allowlist</strong>. Every agent starts with <code>&quot;*&quot;: &quot;deny&quot;</code> and receives only the tools strictly necessary for its role.</p><h3 id="team-lead" tabindex="-1">team-lead <a class="header-anchor" href="#team-lead" aria-label="Permalink to &quot;team-lead&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Access</th></tr></thead><tbody><tr><td><code>task</code>, <code>todowrite</code>, <code>todoread</code>, <code>skill</code>, <code>question</code></td><td>allow</td></tr><tr><td><code>distill</code>, <code>prune</code>, <code>compress</code></td><td>allow (context management)</td></tr><tr><td><code>read</code></td><td>allow on all files</td></tr><tr><td><code>edit</code> / <code>write</code></td><td>allow on <code>docs/**</code> only</td></tr><tr><td><code>bash</code></td><td>allow for git commands only (<code>git status</code>, <code>git diff</code>, <code>git log</code>, <code>git add</code>, <code>git commit</code>, <code>git push</code>, <code>git tag</code>)</td></tr><tr><td>Everything else</td><td>deny</td></tr></tbody></table><h3 id="review-manager" tabindex="-1">review-manager <a class="header-anchor" href="#review-manager" aria-label="Permalink to &quot;review-manager&quot;">​</a></h3><p><code>task</code> and <code>question</code> only. Can read files directly via <code>read</code>, <code>glob</code>, <code>grep</code>.</p><h3 id="specialized-reviewers-requirements-reviewer-code-reviewer-security-reviewer" tabindex="-1">Specialized reviewers (<code>requirements-reviewer</code>, <code>code-reviewer</code>, <code>security-reviewer</code>) <a class="header-anchor" href="#specialized-reviewers-requirements-reviewer-code-reviewer-security-reviewer" aria-label="Permalink to &quot;Specialized reviewers (\`requirements-reviewer\`, \`code-reviewer\`, \`security-reviewer\`)&quot;">​</a></h3><p><code>read</code>, <code>glob</code>, <code>grep</code> for direct file access. Sub-agent spawning is blocked by the default <code>&quot;*&quot;: &quot;deny&quot;</code> rule.</p><h3 id="bug-finder" tabindex="-1">bug-finder <a class="header-anchor" href="#bug-finder" aria-label="Permalink to &quot;bug-finder&quot;">​</a></h3><p>Investigates directly via <code>read</code>, <code>glob</code>, <code>grep</code>. Reports findings back to caller — does not apply fixes itself.</p><h3 id="brainstorm" tabindex="-1">brainstorm <a class="header-anchor" href="#brainstorm" aria-label="Permalink to &quot;brainstorm&quot;">​</a></h3><p><code>task</code>, <code>question</code>, <code>webfetch</code>, <code>read</code> (all project files), <code>edit</code> (<code>docs/briefs/**</code> only). No bash.</p><h3 id="harness" tabindex="-1">harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;harness&quot;">​</a></h3><p><code>task</code>, <code>question</code>, <code>todowrite</code>, <code>todoread</code>, <code>glob</code>, <code>grep</code>, <code>bash</code> (unrestricted), <code>read</code> (all), <code>edit</code> (all), <code>write</code> (all). Full access — harness needs to be able to create and modify any enforcement artifact.</p><h3 id="planning" tabindex="-1">planning <a class="header-anchor" href="#planning" aria-label="Permalink to &quot;planning&quot;">​</a></h3><p><code>task</code>, <code>question</code>, <code>read</code> (<code>AGENTS.md</code>, <code>README.md</code>, <code>docs/**</code>), <code>edit</code>/<code>write</code> (<code>docs/exec-plans/**</code> only).</p><h3 id="gardener" tabindex="-1">gardener <a class="header-anchor" href="#gardener" aria-label="Permalink to &quot;gardener&quot;">​</a></h3><p><code>task</code>, <code>question</code>, <code>bash</code> (<code>git log</code>, <code>git diff</code>, <code>git status</code>, <code>gh pr create</code>), <code>read</code> (all), <code>edit</code>/<code>write</code> (<code>QUALITY_SCORE.md</code> only).</p><div class="tip custom-block"><p class="custom-block-title">Why deny-all?</p><p>An orchestrator that can read files directly tends to read them instead of delegating. The deny-all constraint forces the team-lead to delegate exploration and file access to specialized agents, keeping context clean and responsibilities well-separated.</p></div><h2 id="how-prompts-are-loaded" tabindex="-1">How prompts are loaded <a class="header-anchor" href="#how-prompts-are-loaded" aria-label="Permalink to &quot;How prompts are loaded&quot;">​</a></h2><p>Agent prompts are loaded once at plugin startup via <code>readFile</code>, not inlined in <code>index.js</code>. Paths are resolved from <code>__dirname</code> into <code>agents/</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agents/</span></span>
<span class="line"><span>├── prompt.md               → team-lead</span></span>
<span class="line"><span>├── review-manager.md       → review-manager</span></span>
<span class="line"><span>├── requirements-reviewer.md</span></span>
<span class="line"><span>├── code-reviewer.md</span></span>
<span class="line"><span>├── security-reviewer.md</span></span>
<span class="line"><span>├── bug-finder.md</span></span>
<span class="line"><span>├── harness.md</span></span>
<span class="line"><span>├── planning.md</span></span>
<span class="line"><span>├── gardener.md</span></span>
<span class="line"><span>├── brainstorm.md</span></span>
<span class="line"><span>└── researcher.md           → researcher</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>This means prompts are editable and diffable independently of the plugin code. A prompt change produces a clean diff in the relevant <code>agents/*.md</code> file without touching <code>index.js</code>.</p><h2 id="zero-dependencies" tabindex="-1">Zero dependencies <a class="header-anchor" href="#zero-dependencies" aria-label="Permalink to &quot;Zero dependencies&quot;">​</a></h2><p>No npm dependencies. Only Node.js built-in modules:</p><ul><li><code>node:fs/promises</code> — reading prompt files and artifact directories</li><li><code>node:path</code> — path resolution</li><li><code>node:url</code> — <code>fileURLToPath</code> for <code>__dirname</code> in ESM context</li></ul><p>This is enforced by a CI check on every push — any PR that adds <code>dependencies</code> or <code>devDependencies</code> is automatically blocked.</p>`,46)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
